function setupBookFilters(){const cards=[...document.querySelectorAll('.page-wrap #catalogGrid .book-card, .page-wrap .catalog-grid#catalogGrid .book-card')],genre=document.querySelector('input[name="taleGenre"]:checked')?.value||params.get('genre')||'Все',age=document.querySelector('input[name="taleAge"]:checked')?.value||params.get('age')||'Все',query=(params.get('q')||'').toLocaleLowerCase('ru');let shown=cards.filter(card=>(genre==='Все'||card.dataset.genre===genre)&&(age==='Все'||card.dataset.age===age)&&(!query||card.dataset.search.includes(query)));const sort=document.getElementById('sort');if(sort?.value==='az')shown.sort((a,b)=>a.dataset.search.localeCompare(b.dataset.search,'ru'));if(sort?.value==='time')shown.sort((a,b)=>parseInt(BOOKS.find(book=>book.id===a.dataset.bookId).time)-parseInt(BOOKS.find(book=>book.id===b.dataset.bookId).time));cards.forEach(card=>card.hidden=!shown.includes(card));const count=document.getElementById('countLabel');if(count)count.textContent='Найдено '+shown.length+' '+(shown.length===1?'сказка':'сказок');}
