if(page==='quiz'){let b=BOOKS.find(x=>x.id===params.get('id'))||BOOKS[0],step=0,score=0;let questions=[['Кто автор этой истории?',[b.author,'Александр Пушкин','Корней Чуковский'],0],['Кому подошла бы эта история?',['Маленькому читателю','Никому','Только взрослым'],0],['Что можно обсудить после чтения?',['Поступки героев','Только длину книги','Ничего'],0]];function showQ(){let q=questions[step];document.getElementById('quizQuestion').textContent=`Вопрос ${step+1} из ${questions.length}. ${q[0]}`;document.getElementById('quizProgress').style.width=(step/questions.length*100)+'%';const answerBox=document.getElementById('quizAnswers');answerBox.replaceChildren();q[1].forEach((label,index)=>{const option=document.createElement('button');option.className='quiz-option';option.textContent=label;option.addEventListener('click',()=>{if(index===q[2])score++;step++;if(step<questions.length)showQ();else{document.getElementById('quizProgress').style.width='100%';document.getElementById('quizQuestion').textContent='Готово!';answerBox.replaceChildren();let r=document.getElementById('quizResult');r.hidden=false;r.textContent=`Ваш результат: ${score} из ${questions.length}. Спасибо за игру!`;recordHistory('Прошёл викторину',`Викторина по сказке «${b.title}» · ${score}/${questions.length}`,`quiz.html?id=${b.id}`)}});answerBox.append(option)})}showQ()}
