function initLogic(){let step=0,score=0,answered=false;let book=BOOKS.find(x=>x.id===params.get('id'))||BOOKS[1],questions=LOGIC_SETS[book.id]||[[`Как называется сказка, которую мы повторяем?`,[book.title,'Репка','Колобок'],0],[`Кто написал историю «${book.title}»?`,[book.author,'Корней Чуковский','Русский народ'],0],[`К какому жанру относится эта сказка?`,[book.genre,'Стихи','Загадка'],0],[`Для какого возраста подходит история?`,[book.age,'3–5 лет','9–12 лет'],0],[`Что лучше сделать после прочтения?`,['Вспомнить поступки героев','Забыть историю','Не обсуждать её'],0]];const q=document.getElementById('logicQuestion'),a=document.getElementById('logicAnswers'),feedback=document.getElementById('logicFeedback'),next=document.getElementById('logicNext');function show(){answered=false;const item=questions[step];document.getElementById('logicStep').textContent=`Задание ${step+1} из ${questions.length} · правильных ответов: ${score}`;document.getElementById('logicProgress').style.width=(step/questions.length*100)+'%';q.textContent=item[0];a.replaceChildren();item[1].forEach((label,i)=>{const button=document.createElement('button');button.className='quiz-option';button.textContent=label;button.onclick=()=>{if(answered)return;answered=true;const ok=i===item[2];if(ok)score++;feedback.hidden=false;feedback.textContent=ok?'Верно!':'Пока неверно. Правильный ответ: '+item[1][item[2]];next.hidden=false};a.append(button)});feedback.hidden=true;next.hidden=true}next.onclick=()=>{if(++step<questions.length)show();else{document.getElementById('logicProgress').style.width='100%';q.textContent=`Готово! Ваш результат: ${score} из ${questions.length}`;document.getElementById('logicStep').textContent='';a.replaceChildren();feedback.hidden=true;next.hidden=true;document.getElementById('logicRestart').hidden=false;recordHistory('Завершил логическую задачу',`Задачи по сказке «${book.title}» · ${score}/${questions.length}`,`logic-task.html?id=${book.id}`)}};document.getElementById('logicRestart').onclick=()=>{step=score=0;document.getElementById('logicRestart').hidden=true;show()};show()}
