// BBEditor stores a small safe BBCode vocabulary; only supported tags become HTML.
document.querySelectorAll('[data-bbeditor]').forEach(editor=>{
  const input=editor.querySelector('[data-bbe-input]');
  const panes=[...editor.querySelectorAll('[data-bbe-pane]')];
  const tabs=[...editor.querySelectorAll('[data-bbe-tab]')];
  const preview=editor.querySelector('[data-bbe-pane="preview"]');
  if(!input||!preview)return;
  const renderPreview=()=>{
    const escaped=document.createElement('div');
    escaped.textContent=input.value;
    preview.innerHTML=escaped.innerHTML
      .replace(/\[b\](.*?)\[\/b\]/gis,'<strong>$1</strong>')
      .replace(/\[i\](.*?)\[\/i\]/gis,'<em>$1</em>')
      .replace(/\[u\](.*?)\[\/u\]/gis,'<u>$1</u>')
      .replace(/\[h2\](.*?)\[\/h2\]/gis,'<h2>$1</h2>')
      .replace(/\[quote\](.*?)\[\/quote\]/gis,'<blockquote>$1</blockquote>')
      .replace(/\[list\]/gi,'<ul>').replace(/\[\/list\]/gi,'</ul>')
      .replace(/\[li\](.*?)\[\/li\]/gis,'<li>$1</li>').replace(/\n/g,'<br>');
    if(!input.value.trim())preview.innerHTML='<p class="bbeditor-empty">Предпросмотр появится здесь.</p>';
  };
  const showPane=name=>{
    panes.forEach(pane=>pane.hidden=pane.dataset.bbePane!==name);
    tabs.forEach(tab=>{const active=tab.dataset.bbeTab===name;tab.classList.toggle('is-active',active);tab.setAttribute('aria-selected',String(active))});
    if(name==='preview')renderPreview();
  };
  tabs.forEach(tab=>tab.addEventListener('click',()=>showPane(tab.dataset.bbeTab)));
  editor.querySelectorAll('[data-bbe-command]').forEach(button=>button.addEventListener('click',()=>{
    const command=button.dataset.bbeCommand,start=input.selectionStart,end=input.selectionEnd,selected=input.value.slice(start,end)||'Текст';
    const templates={b:['[b]','[/b]'],i:['[i]','[/i]'],u:['[u]','[/u]'],h2:['[h2]','[/h2]'],quote:['[quote]','[/quote]'],list:['[list][li]','[/li][/list]']};
    const [open,close]=templates[command]||[];
    if(!open)return;
    const replacement=open+selected+close;
    input.setRangeText(replacement,start,end,'select');
    input.focus();
    input.dispatchEvent(new Event('input',{bubbles:true}));
  }));
  input.addEventListener('input',()=>{if(!preview.hidden)renderPreview()});
});

// Administrative content searches and pagination replace only their result region.
const ajaxResultError=(container,message)=>{const notice=document.createElement('p');notice.className='form-errors';notice.setAttribute('role','alert');notice.textContent=message;container.prepend(notice)};
const loadAdminResults=async(url,container)=>{
  if(!container)return;
  container.setAttribute('aria-busy','true');container.classList.add('is-loading');
  try{
    const response=await fetch(url,{headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});
    const data=await response.json();
    if(!response.ok)throw new Error(Object.values(data.errors||{}).flat()[0]||'Не удалось обновить список. Проверьте фильтры и попробуйте ещё раз.');
    container.innerHTML=data.html;
    history.pushState({},'',url);
  }catch(error){ajaxResultError(container,error.message||'Не удалось обновить список. Проверьте соединение и повторите попытку.');}
  finally{container.removeAttribute('aria-busy');container.classList.remove('is-loading');}
};
document.addEventListener('submit',event=>{
  const form=event.target.closest('[data-ajax-filter]');if(!form)return;
  event.preventDefault();
  const url=new URL(form.action,location.href);
  new FormData(form).forEach((value,key)=>{if(String(value).trim())url.searchParams.set(key,String(value));else url.searchParams.delete(key)});
  loadAdminResults(url.toString(),form.nextElementSibling?.matches('[data-ajax-results]')?form.nextElementSibling:null);
});
document.addEventListener('click',event=>{
  const reset=event.target.closest('[data-ajax-filter] a');
  if(reset){
    event.preventDefault();const form=reset.closest('[data-ajax-filter]');
    form.querySelectorAll('input').forEach(input=>input.value='');form.querySelectorAll('select').forEach(select=>select.selectedIndex=0);
    loadAdminResults(reset.href,form.nextElementSibling?.matches('[data-ajax-results]')?form.nextElementSibling:null);return;
  }
  const link=event.target.closest('[data-ajax-results] .pagination a');if(!link)return;
  event.preventDefault();loadAdminResults(link.href,link.closest('[data-ajax-results]'));
});
window.addEventListener('popstate',()=>{
  const container=document.querySelector('[data-ajax-results]');if(!container)return;
  const form=container.previousElementSibling?.matches('[data-ajax-filter]')?container.previousElementSibling:null;
  if(form){const params=new URL(location.href).searchParams;form.querySelectorAll('[name]').forEach(field=>{if(field.type==='search'||field.type==='text')field.value=params.get(field.name)||'';else if(field.tagName==='SELECT')field.value=params.get(field.name)||''})}
  loadAdminResults(location.href,container);
});

// Shared AJAX submission for account, profile, and public interaction forms.
document.querySelectorAll('form[data-ajax-form]').forEach(form=>{
  let feedback=form.querySelector('[data-ajax-feedback]');
  if(!feedback){feedback=document.createElement('div');feedback.className='ajax-form-feedback';feedback.dataset.ajaxFeedback='';feedback.hidden=true;feedback.setAttribute('aria-live','polite');form.prepend(feedback)}
  const fields=[...form.querySelectorAll('input:not([type="hidden"]),select,textarea')];
  const clearError=field=>{
    field.removeAttribute('aria-invalid');
    const wrap=field.closest('.field,.check-line')||field.parentElement;
    const error=wrap?.querySelector(`[data-error-for="${CSS.escape(field.name)}"]`);
    if(error){const descriptions=(field.getAttribute('aria-describedby')||'').split(/\s+/).filter(id=>id&&id!==error.id);if(descriptions.length)field.setAttribute('aria-describedby',descriptions.join(' '));else field.removeAttribute('aria-describedby');error.remove()}
  };
  const fieldError=(field,message)=>{
    if(!field)return;
    clearError(field);field.setAttribute('aria-invalid','true');
    const wrap=field.closest('.field,.check-line')||field.parentElement;
    if(!wrap)return;
    const error=document.createElement('small');error.className='ajax-field-error';error.dataset.errorFor=field.name;form.dataset.ajaxId||=String([...document.forms].indexOf(form)+1);error.id=`ajax-form-${form.dataset.ajaxId}-${field.name.replace(/[^a-z0-9_-]/gi,'-')}-error`;error.textContent=message;
    const descriptions=(field.getAttribute('aria-describedby')||'').split(/\s+/).filter(Boolean);if(!descriptions.includes(error.id))descriptions.push(error.id);field.setAttribute('aria-describedby',descriptions.join(' '));
    wrap.append(error);
  };
  const setFeedback=(message,kind='error')=>{
    feedback.hidden=false;feedback.className=`ajax-form-feedback is-${kind}`;feedback.setAttribute('role',kind==='error'?'alert':'status');feedback.textContent=message;
  };
  const clearErrors=()=>{fields.forEach(clearError);feedback.hidden=true;feedback.textContent='';feedback.className='ajax-form-feedback'};
  fields.forEach(field=>['input','change'].forEach(type=>field.addEventListener(type,()=>{clearError(field);if(!form.querySelector('[aria-invalid="true"]')&&feedback.classList.contains('is-error'))feedback.hidden=true})));
  form.addEventListener('invalid',event=>{
    event.preventDefault();
    const field=event.target;
    fieldError(field,field.validationMessage||'Проверьте это поле.');
    setFeedback('Проверьте обязательные поля и исправьте отмеченные ошибки.');
  },true);
  form.addEventListener('submit',async event=>{
    event.preventDefault();clearErrors();form.setAttribute('aria-busy','true');form.classList.add('is-submitting');
    const submitters=[...form.querySelectorAll('button[type="submit"],input[type="submit"]')];submitters.forEach(button=>button.disabled=true);
    setFeedback('Отправляем данные…','pending');
    try{
      const response=await fetch(form.action,{method:(form.method||'POST').toUpperCase(),body:new FormData(form),headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});
      if(!response.headers.get('content-type')?.includes('application/json'))throw new Error('Сеанс мог завершиться. Обновите страницу и попробуйте снова.');
      let data;try{data=await response.json()}catch{throw new Error('Сервер вернул неполный ответ. Повторите попытку.')}
      if(!response.ok){
        const errors=data.errors||{};let first=null;
        Object.entries(errors).forEach(([name,messages])=>{const field=form.elements.namedItem(name.split('.')[0]);const control=field instanceof RadioNodeList?field[0]:field;if(control){fieldError(control,Array.isArray(messages)?messages[0]:String(messages));first??=control}});
        setFeedback(first?'Проверьте отмеченные поля.':(data.message||'Не удалось отправить форму. Проверьте данные и попробуйте ещё раз.'));
        first?.focus();return;
      }
      setFeedback(data.message||'Изменения сохранены.','success');
      if(form.hasAttribute('data-media-upload')&&data.media){
        const grid=document.querySelector('.media-grid');
        const empty=document.querySelector('.media-library-section .empty-state');
        if(empty){const replacement=document.createElement('div');replacement.className='media-grid';empty.replaceWith(replacement)}
        const targetGrid=grid||document.querySelector('.media-grid');
        if(targetGrid){
          const card=document.createElement('article');card.className='media-card';
          const preview=document.createElement('a');preview.className='media-preview';preview.href=data.media.url;preview.target='_blank';preview.rel='noopener';
          const image=document.createElement('img');image.src=data.media.url;image.alt='';image.loading='lazy';preview.append(image);
          const info=document.createElement('div');info.className='media-card-info';
          const name=document.createElement('strong');name.title=data.media.name;name.textContent=data.media.name;
          const path=document.createElement('code');path.textContent=data.media.path;
          info.append(name,path);
          if(data.media.path&&form.elements.namedItem('select')?.value){const button=document.createElement('button');button.className='button button-small';button.type='button';button.dataset.mediaSelect='';button.dataset.mediaField=form.elements.namedItem('select').value;button.dataset.mediaPath=data.media.path;button.textContent='Выбрать изображение';info.append(button)}else{const open=document.createElement('a');open.className='text-link';open.href=data.media.url;open.target='_blank';open.rel='noopener';open.textContent='Открыть';info.append(open)}
          card.append(preview,info);targetGrid.prepend(card);form.reset();
        }
      }
      if(form.hasAttribute('data-ajax-clear'))form.reset();
      const row=form.closest('tr');
      const moderationCard=form.closest('.moderation-card');
      if(form.closest('.admin-users-table')&&row){
        const results=form.closest('[data-ajax-results]');
        if(results)loadAdminResults(location.href,results);
      }else if(form.closest('.moderation-list')&&moderationCard){
        moderationCard.classList.add('is-updating');
        window.setTimeout(()=>moderationCard.remove(),180);
      }
      if(data.redirect){setFeedback(data.message||'Готово. Переходим…','success');window.setTimeout(()=>location.assign(data.redirect),250)}
    }catch(error){
      setFeedback(error.message||'Не удалось связаться с сервером. Проверьте подключение и повторите попытку.');
    }finally{
      form.removeAttribute('aria-busy');form.classList.remove('is-submitting');submitters.forEach(button=>button.disabled=false);
    }
  });
});
